import React, { useState } from "react";
import "./Schedule.css";

const Schedule = () => {
  const [teamName, setTeamName] = useState("");
  const [teams, setTeams] = useState([]);
  const [tournamentType, setTournamentType] = useState("league");
  const [matches, setMatches] = useState([]);
  const [dateTime, setDateTime] = useState("");

  const addTeam = () => {
    if (teamName.trim() !== "") {
      setTeams([...teams, teamName.trim()]);
      setTeamName("");
    }
  };

  const generateLeagueMatches = () => {
    let generated = [];
    for (let i = 0; i < teams.length; i++) {
      for (let j = i + 1; j < teams.length; j++) {
        generated.push({
          team1: teams[i],
          team2: teams[j],
          dateTime
        });
      }
    }
    setMatches(generated);
  };

  const generateKnockoutMatches = () => {
    let generated = [];
    for (let i = 0; i < teams.length; i += 2) {
      if (teams[i + 1]) {
        generated.push({
          team1: teams[i],
          team2: teams[i + 1],
          dateTime
        });
      }
    }
    setMatches(generated);
  };

  const generateSchedule = () => {
    if (tournamentType === "league") {
      generateLeagueMatches();
    } else {
      generateKnockoutMatches();
    }
  };

  return (
    <div className="schedule-container">
      <h1 className="title">🏆 Tournament Scheduler</h1>

      <div className="card">
        <input
          type="text"
          placeholder="Enter Team Name"
          value={teamName}
          onChange={(e) => setTeamName(e.target.value)}
        />
        <button onClick={addTeam}>Add Team</button>

        <div className="teams">
          {teams.map((team, i) => (
            <span key={i} className="team-chip">{team}</span>
          ))}
        </div>

        <select
          value={tournamentType}
          onChange={(e) => setTournamentType(e.target.value)}
        >
          <option value="league">League</option>
          <option value="knockout">Knockout</option>
        </select>

        <input
          type="datetime-local"
          value={dateTime}
          onChange={(e) => setDateTime(e.target.value)}
        />

        <button className="generate" onClick={generateSchedule}>
          Generate Schedule
        </button>
      </div>

      {matches.length > 0 && (
        <div className="table-wrapper">
          <table className="schedule-table">
            <thead>
              <tr>
                <th>#</th>
                <th>Team A</th>
                <th>Team B</th>
                <th>Date & Time</th>
              </tr>
            </thead>
            <tbody>
              {matches.map((m, i) => (
                <tr key={i}>
                  <td>{i + 1}</td>
                  <td>{m.team1}</td>
                  <td>{m.team2}</td>
                  <td>{m.dateTime || "TBD"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default Schedule;
